// Types for LLM function calls
interface LLMCallParams {
    model: 'balanced' | 'speedster' | 'reasoning';
    instructions: string;
    prompt: string;
}

interface LLMJSONCallParams<T> extends LLMCallParams {
    schema?: string;
}

// Image generation params
interface ImageGenerationParams {
    prompt: string;
}

// Create maps to store callbacks and stream controllers
const pendingCallbacks = new Map<string, {
    resolve: (value: any) => void;
    reject: (reason: any) => void;
}>();

const streamControllers = new Map<string, ReadableStreamDefaultController<any>>();

// Set up message listener for responses from parent
window.addEventListener('message', function (event) {
    const response = event.data;

    // Handle non-streaming responses
    if (response.type === 'llm-response') {
        const callback = pendingCallbacks.get(response.callId);
        if (callback) {
            pendingCallbacks.delete(response.callId);
            if (response.success) {
                callback.resolve(response.result);
            } else {
                callback.reject(new Error(response.error));
            }
        }
    }

    // Handle streaming response chunks
    else if (response.type === 'llm-stream-chunk') {
        const controller = streamControllers.get(response.callId);
        if (controller) {
            if (response.done) {
                controller.close();
                streamControllers.delete(response.callId);
            } else {
                controller.enqueue(response.chunk);
            }
        }
    }
});

// Generate a unique ID for each call
function generateCallId(): string {
    return Math.random().toString(36).substring(2);
}

// String output functions
export async function callLLMString(params: LLMCallParams): Promise<string> {
    const callId = generateCallId();

    return new Promise((resolve, reject) => {
        pendingCallbacks.set(callId, { resolve, reject });

        window.parent.postMessage({
            type: 'llm-call',
            callType: 'string',
            streaming: false,
            params,
            callId
        }, '*');
    });
}

export async function* callLLMAndStreamOutputText(params: LLMCallParams): AsyncGenerator<string, void, unknown> {
    const callId = generateCallId();

    const stream = new ReadableStream<string>({
        start(controller) {
            streamControllers.set(callId, controller);

            window.parent.postMessage({
                type: 'llm-call',
                callType: 'string',
                streaming: true,
                params,
                callId
            }, '*');
        },
        cancel() {
            // Cancel the stream if consumer stops reading
            window.parent.postMessage({
                type: 'llm-stream-cancel',
                callId
            }, '*');

            streamControllers.delete(callId);
        }
    });

    const reader = stream.getReader();

    try {
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            yield value;
        }
    } finally {
        reader.releaseLock();
    }
}

// JSON output functions
export async function callLLMJSON<T>(params: LLMJSONCallParams<T>): Promise<T> {
    const callId = generateCallId();

    return new Promise((resolve, reject) => {
        pendingCallbacks.set(callId, { resolve, reject });

        window.parent.postMessage({
            type: 'llm-call',
            callType: 'json',
            streaming: false,
            params,
            callId
        }, '*');
    });
}

export async function* callLLMAndStreamOutputJSON<T>(params: LLMJSONCallParams<T>): AsyncGenerator<T, void, unknown> {
    const callId = generateCallId();

    const stream = new ReadableStream<T>({
        start(controller) {
            streamControllers.set(callId, controller);

            window.parent.postMessage({
                type: 'llm-call',
                callType: 'json',
                streaming: true,
                params,
                callId
            }, '*');
        },
        cancel() {
            // Cancel the stream if consumer stops reading
            window.parent.postMessage({
                type: 'llm-stream-cancel',
                callId
            }, '*');

            streamControllers.delete(callId);
        }
    });

    const reader = stream.getReader();

    try {
        while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            yield value;
        }
    } finally {
        reader.releaseLock();
    }
}

// Image functions output base64 encoded images
export async function generateImageBase64(params: { prompt: string }): Promise<string> {
    const callId = generateCallId();

    return new Promise((resolve, reject) => {
        pendingCallbacks.set(callId, { resolve, reject });

        window.parent.postMessage({
            type: 'llm-call',
            callType: 'image',
            streaming: false,
            params,
            callId
        }, '*');
    });
}
